local Sprite = require(script.Parent.Parent.apis.Sprite)
local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent)

function module:ctor(element)
	self.super.ctor(self, element)
    self._customScale = 1
    self._sizeChangedConnection = nil
    element:GetPropertyChangedSignal("Parent"):Connect(function()
        if self._sizeChangedConnection then
            self._sizeChangedConnection:Disconnect()
            self._sizeChangedConnection = nil
        end
        self._customScale = 1
        self._sizeChangedConnection = nil
    end)
end

function module:SetTextLines(lines)
    local scale = 1 / lines
    local textLabel: TextLabel = self._element
    textLabel.TextScaled = false
    self._customScale = scale

    self:Scale(scale)
    if self._sizeChangedConnection then
        self._sizeChangedConnection:Disconnect()
        self._sizeChangedConnection = nil
    end
    self._sizeChangedConnection = textLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        self:Scale(scale)
    end)
end

function module:SetTextScale(scale)
    local textLabel: TextLabel = self._element
    textLabel.TextScaled = false
    self._customScale = scale
    
    self:Scale(scale)
    if self._sizeChangedConnection then
        self._sizeChangedConnection:Disconnect()
        self._sizeChangedConnection = nil
    end
    self._sizeChangedConnection = textLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        self:Scale(scale)
    end)
end

function module:Scale(scale)
    local textLabel: TextLabel = self._element
    textLabel.TextScaled = false

    local absoluteSize = textLabel.AbsoluteSize
    local textSize = absoluteSize.Y * scale
    textLabel.TextSize = textSize
end


return module